class Consumer:
    """Reads events and hands batches to the sink."""

    def __init__(self, group, protocol="cooperative-sticky"):
        self.group = group
        self.protocol = protocol

    def poll(self, timeout=1.0):
        raise NotImplementedError

def write_parquet(rows, sink, batch_size=50_000):
    """Stream row groups to `sink` instead of buffering the whole file."""
    for batch in chunked(rows, batch_size):
        sink.write_row_group(batch)

